 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    from collections import Counter
    counts = Counter(v for row in grid for v in row)
    bg = counts.most_common(1)[0][0]
    colors = [c for c in counts if c != bg]
    out = [row[:] for row in grid]
    # For isolated zero markers, construct the bounding rectangle perimeter.
    if 0 in colors:
        pts = [(r,c) for r in range(h) for c in range(w) if grid[r][c] == 0]
        r0,r1=min(r for r,c in pts),max(r for r,c in pts)
        c0,c1=min(c for r,c in pts),max(c for r,c in pts)
        for c in range(c0,c1+1):
            if out[r0][c] == bg: out[r0][c] = 2
            if out[r1][c] == bg: out[r1][c] = 2
        for r in range(r0,r1+1):
            if out[r][c0] == bg: out[r][c0] = 2
            if out[r][c1] == bg: out[r][c1] = 2
        return out
    obj = colors[0] if colors else None
    if obj is not None:
        # Complete long aligned runs, changing only background cells to 2.
        for r in range(h):
            cs = [c for c in range(w) if grid[r][c] == obj]
            if len(cs) >= 2:
                for c in range(min(cs), max(cs)+1):
                    if grid[r][c] == bg: out[r][c] = 2
        for c in range(w):
            rs = [r for r in range(h) if grid[r][c] == obj]
            if len(rs) >= 3:
                for r in range(min(rs), max(rs)+1):
                    if grid[r][c] == bg: out[r][c] = 2
    return out
